package com.sankalp.fairexit.model;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

/**
 * One file in the Evidence Vault. The id is chosen up front (not generated by JPA)
 * because the storage key, which holds the id, is needed before the row is saved.
 */
@Entity
@Table(name = "documents")
public class Document {

    @Id
    private UUID id;

    @Column(name = "tenancy_id", nullable = false, updatable = false)
    private UUID tenancyId;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, updatable = false, length = 20)
    private DocumentType type;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, updatable = false, length = 10)
    private DocumentPhase phase;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 10)
    private DocumentStatus status;

    @Column(name = "file_name", nullable = false, updatable = false, length = 200)
    private String fileName;

    @Column(name = "content_type", nullable = false, updatable = false, length = 50)
    private String contentType;

    @Column(name = "size_bytes", nullable = false, updatable = false)
    private long sizeBytes;

    @Column(updatable = false, length = 60)
    private String room;

    @Column(updatable = false, length = 100)
    private String item;

    @Column(updatable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "storage_key", nullable = false, length = 300)
    private String storageKey;

    @Column(length = 64)
    private String sha256;

    @Column(name = "chain_seq")
    private Integer chainSeq;

    @Column(name = "prev_hash", length = 64)
    private String prevHash;

    @Column(name = "record_hash", length = 64)
    private String recordHash;

    @Column(name = "uploaded_at")
    private Instant uploadedAt;

    @Column(name = "reject_reason", length = 200)
    private String rejectReason;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    protected Document() {
        // for JPA
    }

    public Document(UUID id, UUID tenancyId, DocumentType type, DocumentPhase phase, String fileName,
                    String contentType, long sizeBytes, String room, String item, BigDecimal amount,
                    String stagingKey) {
        this.id = id;
        this.tenancyId = tenancyId;
        this.type = type;
        this.phase = phase;
        this.status = DocumentStatus.PENDING;
        this.fileName = fileName;
        this.contentType = contentType;
        this.sizeBytes = sizeBytes;
        this.room = room;
        this.item = item;
        this.amount = amount;
        this.storageKey = stagingKey;
        this.createdAt = Instant.now();
    }

    /** The file is now in the vault, hashed, and linked into the tenancy's chain. */
    public void markStored(String vaultKey, String sha256, int chainSeq, String prevHash,
                           String recordHash, Instant uploadedAt) {
        if (status != DocumentStatus.PENDING) {
            throw new IllegalStateException("Only a pending document can be stored");
        }
        this.storageKey = vaultKey;
        this.sha256 = sha256;
        this.chainSeq = chainSeq;
        this.prevHash = prevHash;
        this.recordHash = recordHash;
        this.uploadedAt = uploadedAt;
        this.status = DocumentStatus.STORED;
    }

    public void reject(String reason) {
        this.status = DocumentStatus.REJECTED;
        this.rejectReason = reason;
    }

    public boolean isStored() {
        return status == DocumentStatus.STORED;
    }

    public UUID getId() {
        return id;
    }

    public UUID getTenancyId() {
        return tenancyId;
    }

    public DocumentType getType() {
        return type;
    }

    public DocumentPhase getPhase() {
        return phase;
    }

    public DocumentStatus getStatus() {
        return status;
    }

    public String getFileName() {
        return fileName;
    }

    public String getContentType() {
        return contentType;
    }

    public long getSizeBytes() {
        return sizeBytes;
    }

    public String getRoom() {
        return room;
    }

    public String getItem() {
        return item;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public String getStorageKey() {
        return storageKey;
    }

    public String getSha256() {
        return sha256;
    }

    public Integer getChainSeq() {
        return chainSeq;
    }

    public String getPrevHash() {
        return prevHash;
    }

    public String getRecordHash() {
        return recordHash;
    }

    public Instant getUploadedAt() {
        return uploadedAt;
    }

    public String getRejectReason() {
        return rejectReason;
    }
}
